package com.daniil.wristlens.wear;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.shadows.*;import com.daniil.wristlens.shared.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34,qualifiers="en-rUS-w240dp-h240dp-round-xhdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE) @LooperMode(LooperMode.Mode.PAUSED)
public class DownloadFeedbackTest {
 Activity a;@Before public void setup(){a=Robolectric.buildActivity(Activity.class).setup().get();Strings.init(a);DownloadTestDispatch.install(a);}@After public void after(){DownloadTestDispatch.restore();for(Dialog d:new ArrayList<>(ShadowDialog.getShownDialogs()))d.dismiss();a.finish();}
 JSONObject file(String id){return Wire.object("id",id,"name","IMG_"+id+".jpg","bytes",10000,"sequence",12);}
 @Test public void queuesBatchOnlyOnceAndSurvivesActivityClosure(){String id=Downloads.enqueue(a,"phone",List.of(file("a"),file("b")));assertEquals(1,DownloadTestDispatch.enqueued.size());assertEquals("",Downloads.enqueue(a,"phone",List.of(file("a"))));assertEquals(2,Downloads.current(a,id).count());assertEquals(Downloads.QUEUED,Downloads.state(a,"phone","b").phase());}
 @Test public void actualCompressedSizeDrivesProgressAndCancelAction()throws Exception{String id=Downloads.enqueue(a,"phone",List.of(file("a")));Downloads.update(a,id,"a",Downloads.RUNNING,500,1000,"compressed.jpg");var f=Downloads.foreground(a,id);Notification n=f.getNotification();assertEquals(50,n.extras.getInt(Notification.EXTRA_PROGRESS));assertFalse(n.extras.getBoolean(Notification.EXTRA_PROGRESS_INDETERMINATE));assertEquals("compressed.jpg",n.extras.getString(Notification.EXTRA_TITLE));Intent intent=Shadows.shadowOf(n.actions[0].actionIntent).getSavedIntent();assertEquals(DownloadCancelReceiver.class.getName(),intent.getComponent().getClassName());new DownloadCancelReceiver().onReceive(a,intent);assertTrue(Downloads.cancelled(a,id));assertEquals(1,DownloadTestDispatch.cancelled.size());}
 @Test public void preparationIsIndeterminate(){String id=Downloads.enqueue(a,"phone",List.of(file("a")));Downloads.update(a,id,"a",Downloads.PREPARING,0,0,null);Notification n=Downloads.foreground(a,id).getNotification();assertTrue(n.extras.getBoolean(Notification.EXTRA_PROGRESS_INDETERMINATE));assertEquals(Strings.tr(com.daniil.wristlens.shared.R.string.copy_preparing),Downloads.label(Downloads.current(a,id)));}
 @Test public void cancelKeepsCompletedFilesAndLateProgressCannotRestart(){String id=Downloads.enqueue(a,"phone",List.of(file("a"),file("b")));Downloads.update(a,id,"a",Downloads.COMPLETE,10000,10000,null);Downloads.cancel(a,id);Downloads.update(a,id,"b",Downloads.RUNNING,500,1000,null);assertEquals(Downloads.COMPLETE,Downloads.state(a,"phone","a").phase());assertEquals(Downloads.CANCELLED,Downloads.state(a,"phone","b").phase());}
 @Test public void automaticCancelSkipsOnlyCurrentSequence(){a.getSharedPreferences("auto_save",0).edit().clear().commit();AutoSave.prefs(a).edit().putLong("cursor",10).commit();String id=Downloads.create(a,"phone",List.of(file("a")),true,UUID.randomUUID());Downloads.update(a,id,"a",Downloads.RUNNING,1,100,null);Downloads.cancel(a,id);assertEquals(12,AutoSave.prefs(a).getLong("cursor",0));assertEquals(41,Downloads.notificationId(a,id));}
 @Test public void galleryShowsProgressWithoutRebuildingRows()throws Exception{GallerySettingsTest.FakeMedia media=new GallerySettingsTest.FakeMedia(a);Gallery gallery=new Gallery(a,media);try{a.getPreferences(0).edit().putBoolean("gallery_tiles",false).commit();String id=Downloads.create(a,"node",List.of(file("1")),false,UUID.randomUUID());Downloads.update(a,id,"1",Downloads.RUNNING,40,100,null);gallery.open();Dialog d=ShadowDialog.getLatestDialog();RoundMenuFrame root=RoundMenuTest.frame(d);RoundMenuTest.layout(root,480);Shadows.shadowOf(Looper.getMainLooper()).idle();assertTrue(GallerySettingsTest.has(d,"Downloading · 40%"));RoundMenuTest.save(root,"downloads-list");Downloads.update(a,id,"1",Downloads.RUNNING,75,100,null);Shadows.shadowOf(Looper.getMainLooper()).idleFor(java.time.Duration.ofMillis(600));assertTrue(GallerySettingsTest.has(d,"Downloading · 75%"));}finally{gallery.destroy();media.close();}}
 @Test public void failedFileCanBeRetriedImmediatelyWithoutStaleStatus(){String first=Downloads.enqueue(a,"phone",List.of(file("a")));Downloads.finish(a,first,Downloads.ERROR);assertEquals("Download failed",Downloads.label(Downloads.state(a,"phone","a")));String retry=Downloads.enqueue(a,"phone",List.of(file("a")));assertNotEquals(first,retry);assertEquals(retry,Downloads.state(a,"phone","a").job());assertEquals(Downloads.QUEUED,Downloads.state(a,"phone","a").phase());assertEquals(2,DownloadTestDispatch.enqueued.size());}
}
